<template><el-button text @click="visible=true"><el-icon><Setting/></el-icon><span>外观设置</span></el-button><el-drawer v-model="visible" title="工作台外观" size="340px" append-to-body><el-form label-position="top" @submit.prevent><el-form-item label="主题风格"><div class="theme-options"><button type="button" v-for="item in themes" :key="item.value" :class="{selected:theme===item.value}" @click="theme=item.value"><span :style="{background:item.color}"></span>{{item.label}}<el-icon v-if="theme===item.value"><Check/></el-icon></button></div></el-form-item><el-divider/><el-form-item label="页面水印"><el-switch v-model="watermark" active-text="显示账号水印"/></el-form-item><el-form-item label="水印文字"><el-input v-model="watermarkText" maxlength="30" show-word-limit placeholder="花海摄影 · 内部资料"/></el-form-item><el-form-item label="水印透明度"><el-slider v-model="opacity" :min="4" :max="20" :format-tooltip="v=>v+'%'"/></el-form-item><el-alert title="外观偏好会保存在当前浏览器。水印包含登录账号，仅用于页面标识。" type="info" :closable="false"/><el-button class="reset-preferences" @click="reset">恢复默认外观</el-button></el-form></el-drawer><Teleport to="body"><div v-if="watermark" class="workspace-watermark" :style="{backgroundImage:watermarkImage,opacity:opacity/100}" aria-hidden="true"/></Teleport></template>
<script setup>
import {ref,watch,computed,onBeforeUnmount} from 'vue'
const props=defineProps({account:String,role:String})
let saved={};try{saved=JSON.parse(localStorage.getItem('huahai-appearance')||'{}')}catch{}
const themes=[{value:'blue',label:'经典蓝',color:'#409eff'},{value:'forest',label:'松林绿',color:'#288369'},{value:'violet',label:'鸢尾紫',color:'#7861c9'},{value:'slate',label:'深色夜间',color:'#202735'}]
const visible=ref(false),theme=ref(themes.some(t=>t.value===saved.theme)?saved.theme:'blue'),watermark=ref(saved.watermark===true),watermarkText=ref(typeof saved.text==='string'?saved.text:'花海摄影 · 内部资料'),opacity=ref(Math.min(20,Math.max(4,Number(saved.opacity)||8)))
watch([theme,watermark,watermarkText,opacity],()=>{document.documentElement.dataset.workspaceTheme=theme.value;localStorage.setItem('huahai-appearance',JSON.stringify({theme:theme.value,watermark:watermark.value,text:watermarkText.value,opacity:opacity.value}))},{immediate:true})
const escape=s=>String(s||'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))
const watermarkImage=computed(()=>{const svg='<svg xmlns="http://www.w3.org/2000/svg" width="340" height="230"><g transform="translate(170 115) rotate(-24)" text-anchor="middle" fill="'+(theme.value==='slate'?'#c9d2e0':'#344054')+'" font-family="Microsoft YaHei,sans-serif" font-size="14"><text y="-8">'+escape(watermarkText.value)+'</text><text y="16">'+escape(props.account)+' · '+escape(props.role)+'</text></g></svg>';return 'url("data:image/svg+xml,'+encodeURIComponent(svg)+'")'})
function reset(){theme.value='blue';watermark.value=false;watermarkText.value='花海摄影 · 内部资料';opacity.value=8}
onBeforeUnmount(()=>delete document.documentElement.dataset.workspaceTheme)
</script>
<style>
.workspace-watermark{position:fixed;inset:0;pointer-events:none;z-index:3500;background-repeat:repeat}.theme-options{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%}.theme-options button{display:flex;align-items:center;gap:8px;padding:12px 8px;border:1px solid var(--el-border-color);border-radius:8px;cursor:pointer;background:var(--el-bg-color);color:var(--el-text-color-primary)}.theme-options button.selected{border-color:var(--el-color-primary);color:var(--el-color-primary)}.theme-options button>span{width:16px;height:16px;border-radius:50%}.reset-preferences{margin-top:24px}
</style>
